Changes:

1. Add imports near the top of platform/cli/src/commands/tool.ts:
```
import { readFile } from 'node:fs/promises';
```

2. Add a `readParamsSource` async helper above handleToolCall. It returns either `{ json: string; origin: string }` (origin is used in error messages) or undefined when no source was provided. It also enforces mutual exclusion:
```
interface ParamsSource {
  json: string;
  origin: string;
}

const readParamsSource = async (
  jsonArg: string | undefined,
  params: string | undefined,
  paramsFile: string | undefined,
): Promise<ParamsSource | undefined> => {
  const sources: string[] = [];
  if (jsonArg !== undefined) sources.push('[json]');
  if (params !== undefined) sources.push('--params');
  if (paramsFile !== undefined) sources.push('--params-file');

  if (sources.length > 1) {
    console.error(pc.red(`Specify only one of: ${sources.join(', ')}`));
    process.exit(2);
  }

  if (paramsFile !== undefined) {
    if (paramsFile === '-') {
      const chunks: Buffer[] = [];
      for await (const chunk of process.stdin) {
        chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk as string));
      }
      return { json: Buffer.concat(chunks).toString('utf8'), origin: 'stdin' };
    }
    try {
      const json = await readFile(paramsFile, 'utf8');
      return { json, origin: paramsFile };
    } catch (err: unknown) {
      console.error(pc.red(`Failed to read params file ${paramsFile}: ${toErrorMessage(err)}`));
      process.exit(2);
    }
  }

  if (params !== undefined) return { json: params, origin: '--params' };
  if (jsonArg !== undefined) return { json: jsonArg, origin: '[json]' };
  return undefined;
};
```

3. Rewrite the JSON parse section inside handleToolCall. Replace the existing block that uses `rawJson`:
```
  const source = await readParamsSource(jsonArg, options.params, options.paramsFile);
  let args: Record<string, unknown> = {};
  if (source) {
    try {
      args = JSON.parse(source.json) as Record<string, unknown>;
    } catch (err: unknown) {
      const label = source.origin === 'stdin' ? 'stdin' : source.origin === '--params' || source.origin === '[json]'
        ? source.origin
        : source.origin;
      const location = source.origin === 'stdin'
        ? 'on stdin'
        : source.origin === '--params' || source.origin === '[json]'
          ? ''
          : `in ${source.origin}`;
      const prefix = location ? `Invalid JSON ${location}` : 'Invalid JSON';
      console.error(pc.red(`${prefix}: ${toErrorMessage(err)}`));
      process.exit(2);
    }
  }
```
IMPORTANT: unlike the current implementation, do NOT echo the raw JSON blob (`rawJson`) in the error message — for large files this would spam stderr. Echo only the JSON.parse error (position/token info) prefixed with the source origin.

4. Update the options type on handleToolCall:
```
