2. Create platform/cli/src/commands/tool.test.ts. Suggested structure:
```
import { mkdtemp, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { Readable } from 'node:stream';
import { afterAll, beforeAll, describe, expect, test, vi } from 'vitest';
import { readParamsSource } from './tool.js';

let dir: string;
beforeAll(async () => { dir = await mkdtemp(join(tmpdir(), 'opentabs-tool-test-')); });
afterAll(async () => { await rm(dir, { recursive: true, force: true }); });

describe('readParamsSource', () => {
  test('returns undefined when no source is provided', async () => {
    const result = await readParamsSource(undefined, undefined, undefined);
    expect(result).toBeUndefined();
  });

  test('reads JSON from --params-file path', async () => {
    const path = join(dir, 'payload.json');
    await writeFile(path, '{"hello":"world"}', 'utf8');
    const result = await readParamsSource(undefined, undefined, path);
    expect(result).toEqual({ json: '{"hello":"world"}', origin: path });
  });

  test('reads JSON from stdin when --params-file is -', async () => {
    const stdin = Readable.from([Buffer.from('{"x":1}')]);
    const originalStdin = process.stdin;
    // @ts-expect-error — reassigning for test
    process.stdin = stdin as unknown as typeof process.stdin;
    try {
      const result = await readParamsSource(undefined, undefined, '-');
      expect(result).toEqual({ json: '{"x":1}', origin: 'stdin' });
    } finally {
      // @ts-expect-error — restoring
      process.stdin = originalStdin;
    }
  });

  test('exits code 2 when multiple sources are given', async () => {
    const exit = vi.spyOn(process, 'exit').mockImplementation((() => { throw new Error('exit'); }) as never);
    const err = vi.spyOn(console, 'error').mockImplementation(() => {});
    try {
      await expect(readParamsSource('{"a":1}', '{"b":2}', undefined)).rejects.toThrow('exit');
      expect(err).toHaveBeenCalledWith(expect.stringMatching(/Specify only one of:.*\[json\].*--params/));
      expect(exit).toHaveBeenCalledWith(2);
    } finally {
      exit.mockRestore();
      err.mockRestore();
    }
  });

  test('exits code 2 when --params-file points to a missing file', async () => {
    const exit = vi.spyOn(process, 'exit').mockImplementation((() => { throw new Error('exit'); }) as never);
    const err = vi.spyOn(console, 'error').mockImplementation(() => {});
    try {
      await expect(readParamsSource(undefined, undefined, '/nonexistent/path.json')).rejects.toThrow('exit');
      expect(err).toHaveBeenCalledWith(expect.stringMatching(/Failed to read params file \/nonexistent\/path\.json/));
      expect(exit).toHaveBeenCalledWith(2);
    } finally {
      exit.mockRestore();
      err.mockRestore();
    }
  });

  test('round-trips a 2 MB JSON payload without truncation', async () => {
    const bigString = 'x'.repeat(2 * 1024 * 1024);
    const path = join(dir, 'big.json');
    await writeFile(path, JSON.stringify({ data: bigString }), 'utf8');
    const result = await readParamsSource(undefined, undefined, path);
    expect(result).toBeDefined();
    const parsed = JSON.parse(result?.json ?? '') as { data: string };
    expect(parsed.data.length).toBe(2 * 1024 * 1024);
    expect(parsed.data).toBe(bigString);
  });
});
```

Constraints:
- Do NOT import from dist/ — import from ./tool.js so TypeScript project references resolve the source.
- Do NOT leave process.exit or console.error spies unrestored — use try/finally blocks in each test to prevent cross-test pollution.
- Do NOT depend on an actual running MCP server — these are pure unit tests.
- The tmpdir cleanup in afterAll must use `{ recursive: true, force: true }` so a failing test doesn't prevent cleanup.

Trap warning: Vitest does NOT auto-mock process.stdin. The Readable.from trick works because process.stdin is the same async-iterable interface. Don't try to mock it with vi.fn() — it must remain iterable. Also note: process.exit is typed as `(code?: number) => never`, so the mock implementation must match — cast with `as never` on the mockImplementation arrow function body that throws (so the test can assert without actually exiting the test process).

Files:
- e2e/tool-call-large-payload.e2e.ts (new file)

Context:
Existing E2E tests exercise the HTTP layer directly (e.g. e2e/tool-http-api.e2e.ts). This story is different: we must drive the real `opentabs tool call` subprocess so we actually exercise the argv boundary. setupToolTest in e2e/helpers.ts (line 247) already sets up an MCP server with the e2e-test plugin and waits for the `e2e-test_get_status` tool to report ready. The e2e-test plugin has an `echo` tool (plugins/e2e-test/src/tools/echo.ts) that takes `{ message: string }` and returns `{ ok, message }` — perfect for round-trip testing.

The macOS ARG_MAX is 1_048_576 bytes (use `getconf ARG_MAX` to confirm; the CLI binary path + env also count). A 1.5 MB payload is reliably above the limit on both macOS and Linux CI runners.

Reference — CLI subprocess invocation pattern from platform/cli/src/cli-smoke.test.ts (lines 1-48):
```
const CLI = fileURLToPath(new URL('../dist/cli.js', import.meta.url));
const { stdout, stderr } = await execFile('node', [CLI, 'tool', 'call', ...], {
  env: { ...process.env, OPENTABS_CONFIG_DIR: tmpDir },
  timeout: 10_000,
});
```
But that test file lives in platform/cli/src/ and is a vitest unit-level smoke test. Our new E2E test lives in e2e/ under Playwright.

Reference — Playwright E2E test style from e2e/tool-http-api.e2e.ts (lines 37-60):
```
import { expect, test } from './fixtures.js';
import { setupToolTest } from './helpers.js';

test.describe('...', () => {
  test('...', async ({ mcpServer, testServer, extensionContext, mcpClient }) => {
    await setupToolTest(mcpServer, testServer, extensionContext, mcpClient);
    // ...
  });
});
```

